from PySide6.QtCore import Signal
from PySide6.QtWidgets import (
    QHBoxLayout,
    QLineEdit,
    QWidget,
)

from kris_ui.styles.colors import DARK_THEME, LIGHT_THEME
from kris_ui.styles.theme_manager import get_system_theme


class ParameterInput(QWidget):
    """Text input widget for entering parameter keywords.

    Provides a styled text field with placeholder text. Emits add_requested
    signal when user presses Enter with valid (non-empty) text. Automatically
    clears after successful add.

    Signals:
        add_requested: Emitted when Enter is pressed with valid text.
            Provides the trimmed text as argument.

    Example:
        >>> widget = ParameterInput()
        >>> widget.add_requested.connect(handle_add)
    """

    # Layout constants
    _PADDING_H: int = 8
    _PADDING_V: int = 4
    _BORDER_RADIUS: int = 4
    _FONT_SIZE: int = 13

    add_requested = Signal(str)

    def __init__(self, parent: QWidget | None = None) -> None:
        """Initialize the parameter input widget.

        Args:
            parent: Optional parent widget.
        """
        super().__init__(parent)
        self._setup_ui()
        self._connect_signals()
        self._apply_theme()

    def _setup_ui(self) -> None:
        """Set up widget layout with line edit."""
        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        self._line_edit = QLineEdit()
        self._line_edit.setObjectName("ParameterInputLineEdit")
        self._line_edit.setPlaceholderText(
            self.tr("Type parameter name and press Enter")
        )
        layout.addWidget(self._line_edit)

    def _connect_signals(self) -> None:
        """Connect line edit signals."""
        self._line_edit.returnPressed.connect(self._on_return_pressed)

    def _on_return_pressed(self) -> None:
        """Handle Enter/Return key press."""
        text = self._line_edit.text().strip()
        if not text:
            return

        self.add_requested.emit(text)
        self._line_edit.clear()

    def _apply_theme(self) -> None:
        """Apply theme-aware styling."""
        theme = get_system_theme()
        colors = DARK_THEME if theme == "dark" else LIGHT_THEME

        self._line_edit.setStyleSheet(
            f"""
            QLineEdit#ParameterInputLineEdit {{
                background-color: {colors.surface};
                border: 1px solid {colors.border};
                border-radius: {self._BORDER_RADIUS}px;
                padding: {self._PADDING_V}px {self._PADDING_H}px;
                font-size: {self._FONT_SIZE}px;
                color: {colors.text_primary};
            }}
            QLineEdit#ParameterInputLineEdit:focus {{
                border-color: {colors.accent};
                border-width: 2px;
            }}
            QLineEdit#ParameterInputLineEdit::placeholder {{
                color: {colors.text_secondary};
            }}
            """
        )

    @property
    def text(self) -> str:
        """Get the current input text.

        Returns:
            The current text in the input field.
        """
        return self._line_edit.text()

    def clear(self) -> None:
        """Clear the input field."""
        self._line_edit.clear()

    def refresh_theme(self) -> None:
        """Re-apply theme styling after system theme change."""
        self._apply_theme()

    def focus_input(self) -> None:
        """Set keyboard focus to the input field."""
        self._line_edit.setFocus()
