        self._remove_button.setObjectName("KeywordChipRemoveButton")
        self._remove_button.setFixedSize(self._BUTTON_SIZE, self._BUTTON_SIZE)
        self._remove_button.setMinimumSize(self._BUTTON_SIZE, self._BUTTON_SIZE)
        self._remove_button.setCursor(Qt.CursorShape.PointingHandCursor)
        self._remove_button.clicked.connect(self._on_remove_clicked)
        layout.addWidget(self._remove_button)

        # Set size policy and minimum height
        self.setMinimumHeight(self._MIN_HEIGHT)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

    def _on_remove_clicked(self) -> None:
        """Handle remove button click."""
        self.remove_clicked.emit(self._text)

    def _apply_theme(self) -> None:
        """Apply theme-aware styling."""
        theme = get_system_theme()
        colors = DARK_THEME if theme == "dark" else LIGHT_THEME

        # Determine text color for accent background
